"""
doc_extensions.py
=================

Extended content for ``generate_documentation.py``.

* ``cost_benefit_roi()``  -- a fully *computed* financial model.  Every NPV,
  payback, ROI and sensitivity figure is calculated at build time from the
  assumption tables below, so changing one assumption re-flows every number
  in the document consistently.
* ``chapterN_extra()``    -- additional sections appended to chapters 3-7.
* ``appendices()``        -- appendix chapter (decision tables generated by the
  live diagnostic engine, glossary, UAT results, ROI worksheet).

The module is bound to the running generator through ``bind(module)`` so it
shares the same ``Builder`` instance and helper aliases (H1, P, TBL, ...).
"""

from __future__ import annotations

G = None  # the running generate_documentation module (set by bind())


def bind(module):
    global G
    G = module


# Thin proxies onto the generator's helpers ----------------------------------
def H1(t): return G.H1(t)
def H2(t): return G.H2(t)
def H3(t): return G.H3(t)
def P(t, **kw): return G.P(t, **kw)
def BUL(items): return G.BUL(items)
def TBL(title, headers, rows, widths=None, **kw): return G.TBL(title, headers, rows, widths, **kw)
def FIG(title, desc, h=3.0): return G.FIG(title, desc, h)
def NOTE(title, text, kind="info"): return G.NOTE(title, text, kind)
def EQ(expr, note=None): return G.EQ(expr, note)
def CODE(title, rel, **kw): return G.CODE(title, rel, **kw)


def money(x):
    sign = "-" if x < 0 else ""
    return f"{sign}${abs(x):,.2f}"


# ===========================================================================
# FINANCIAL MODEL (single source of truth)
# ===========================================================================
DISCOUNT_RATE = 0.10
HORIZON_YEARS = 5

UNIT_CAPEX = [  # per-site hardware bill of materials
    ("ESP32-WROOM-32 development board", 7.00),
    ("ACS712 current sensor module", 4.00),
    ("Precision voltage divider (10 k\u03a9 / 20 k\u03a9, 1 %) and passives", 1.00),
    ("LM2596 buck converter (12 V \u2192 5 V supply)", 2.00),
    ("IP65 ABS enclosure with cable glands", 6.00),
    ("Terminal blocks, fuse holder and wiring", 4.00),
    ("Installation labour (30 minutes, local technician)", 10.00),
]
UNIT_OPEX = [  # per-site annual operating costs
    ("Cloud hosting share (VPS + PostgreSQL)", 3.00),
    ("Notification channel allowance (e-mail / future SMS)", 2.00),
    ("Maintenance & firmware support allowance", 3.00),
]
SCENARIOS = {  # annual benefit components per site (USD)
    "Pessimistic": {"battery": 50.0, "energy": 15.0, "callouts": 0.0},
    "Expected": {"battery": 150.0, "energy": 29.0, "callouts": 30.0},
    "Optimistic": {"battery": 250.0, "energy": 45.0, "callouts": 60.0},
}


def annuity_factor(r=DISCOUNT_RATE, n=HORIZON_YEARS):
    return (1 - (1 + r) ** -n) / r


def model(scn="Expected"):
    capex = sum(c for _, c in UNIT_CAPEX)
    opex = sum(c for _, c in UNIT_OPEX)
    benefit = sum(SCENARIOS[scn].values())
    net = benefit - opex
    af = annuity_factor()
    npv = -capex + net * af
    payback_months = capex / net * 12 if net > 0 else float("inf")
    total_cost = capex + opex * HORIZON_YEARS
    total_benefit = benefit * HORIZON_YEARS
    roi = (total_benefit - total_cost) / total_cost * 100
    pv_b = benefit * af
    pv_c = capex + opex * af
    return dict(capex=capex, opex=opex, benefit=benefit, net=net, npv=npv,
                payback_months=payback_months, roi=roi, bcr=pv_b / pv_c,
                pv_b=pv_b, pv_c=pv_c)


def cost_benefit_roi():
    m = model()
    af = annuity_factor()

    H3("2.3.3 Unit Economics: The Per-Site Business Case")
    P("The prototype budget above describes what it cost to *build* the project. A more useful question "
      "for an owner in Harare, Bulawayo or a rural growth point is: **what does one TelePower Guard cost "
      "per site, and how quickly does it pay for itself?** The model below answers that question. All "
      "figures in this section are computed by the documentation generator from a single assumption "
      "table, so the tables, equations and conclusions can never contradict each other.")
    TBL("Per-Site Capital Expenditure (Bill of Materials)", ["Component", "Unit Cost (USD)"],
        [[n, money(c)] for n, c in UNIT_CAPEX] + [["**Total CapEx per site**", f"**{money(m['capex'])}**"]],
        [4.5, 1.5], center_cols=(1,))
    TBL("Per-Site Annual Operating Expenditure", ["Item", "Annual Cost (USD)"],
        [[n, money(c)] for n, c in UNIT_OPEX] + [["**Total OpEx per site per year**", f"**{money(m['opex'])}**"]],
        [4.5, 1.5], center_cols=(1,))

    H3("2.3.4 Quantified Benefits")
    P("Benefits are modelled as *expected avoided losses* for a typical 2 kW off-grid or hybrid system "
      "with a lead-acid or lithium battery bank \u2014 the configuration most common among Zimbabwean "
      "households that adopted solar in response to extended ZESA load-shedding schedules.")
    e = SCENARIOS["Expected"]
    TBL("Expected Annual Benefit Derivation (2 kW Site)", ["Benefit Stream", "Derivation", "USD / year"], [
        ["Avoided battery damage", "Undetected deep-discharge / over-charge risk falls from ~30 % to ~5 % per year on a ~$600 bank (0.25 \u00d7 $600).", money(e["battery"])],
        ["Recovered energy yield", "2 kW \u00d7 5.5 peak-sun-hours \u00d7 365 = 4,015 kWh/yr; early soiling/shading alerts recover ~6 % (241 kWh) valued at ~$0.12/kWh displaced grid/diesel energy.", money(e["energy"])],
        ["Avoided technician call-outs", "Remote diagnosis removes ~2 exploratory visits per year at ~$15 each.", money(e["callouts"])],
        ["**Total expected benefit**", "", f"**{money(m['benefit'])}**"],
    ], [1.6, 3.6, 1.0], center_cols=(2,))

    H3("2.3.5 Discounted Cash-Flow Analysis")
    P(f"Cash flows are discounted at **{DISCOUNT_RATE:.0%}** per year over a **{HORIZON_YEARS}-year** "
      "horizon (the conservative service life of the edge electronics).")
    EQ("NPV = \u2212C\u2080 + \u03a3 (B\u209c \u2212 O\u209c) / (1 + r)\u1d57 ,  t = 1 \u2026 n", "Net Present Value")
    EQ("Payback (months) = C\u2080 / (B \u2212 O) \u00d7 12", "Simple payback period")
    rows, cum, dcum = [], -m["capex"], -m["capex"]
    rows.append(["0", money(-m["capex"]), money(-m["capex"]), money(cum), money(dcum)])
    for t in range(1, HORIZON_YEARS + 1):
        disc = m["net"] / (1 + DISCOUNT_RATE) ** t
        cum += m["net"]
        dcum += disc
        rows.append([str(t), money(m["net"]), money(disc), money(cum), money(dcum)])
    TBL("Five-Year Cash Flow per Site (Expected Scenario)",
        ["Year", "Net Cash Flow", "Discounted CF", "Cumulative CF", "Cumulative Discounted CF"],
        rows, [0.6, 1.3, 1.3, 1.4, 1.7], center_cols=(0, 1, 2, 3, 4))
    TBL("Headline Financial Indicators (Expected Scenario)", ["Indicator", "Value", "Interpretation"], [
        ["Net Present Value (5 yr, 10 %)", money(m["npv"]), "Strongly positive \u2014 accept."],
        ["Simple payback period", f"{m['payback_months']:.1f} months", "Recovered within the first season."],
        ["5-year ROI (undiscounted)", f"{m['roi']:,.0f} %", "Each $1 spent returns many times its cost."],
        ["Benefit\u2013Cost Ratio (discounted)", f"{m['bcr']:.1f} : 1", "BCR > 1 indicates economic viability."],
        ["Annuity factor used", f"{af:.4f}", f"r = {DISCOUNT_RATE:.0%}, n = {HORIZON_YEARS}"],
    ], [2.2, 1.4, 2.6], center_cols=(1,))

    H3("2.3.6 Sensitivity and Break-Even Analysis")
    P("Because benefit estimates carry uncertainty, three scenarios were evaluated. The decision is "
      "robust: even the pessimistic case \u2014 which assumes *no* avoided call-outs and only a third "
      "of the expected battery protection \u2014 returns a positive NPV.")
    srows = []
    for name in SCENARIOS:
        s = model(name)
        srows.append([name, money(s["benefit"]), money(s["net"]), money(s["npv"]),
                      f"{s['payback_months']:.1f} mo", f"{s['bcr']:.1f}"])
    TBL("Scenario Sensitivity Analysis", ["Scenario", "Annual Benefit", "Net / Year", "NPV (5 yr)",
                                          "Payback", "BCR"], srows,
        [1.2, 1.1, 1.0, 1.1, 0.9, 0.7], center_cols=(1, 2, 3, 4, 5))
    breakeven = m["opex"] + m["capex"] / af
    NOTE("Break-Even Insight",
         f"The system breaks even (NPV = 0) if it delivers just **{money(breakeven)} of value per year** "
         f"\u2014 roughly the cost of {breakeven / 15:.1f} technician call-out(s), or about "
         f"{breakeven / 0.12:,.0f} kWh of recovered energy. A single prevented battery failure "
         "therefore funds the device for its entire service life.", "ok")

    H3("2.3.7 Platform Economies of Scale")
    P("Fixed cloud costs are shared across every site connected to the platform, so per-site OpEx "
      "falls sharply as adoption grows \u2014 an important consideration for installers or NGOs "
      "rolling the system out across a community.")
    scale = [(1, 120), (10, 120), (100, 120), (1000, 480), (5000, 1440)]
    TBL("Hosting Cost per Site at Different Fleet Sizes",
        ["Connected Sites", "Annual Hosting (USD)", "Hosting per Site", "Infrastructure Tier"],
        [[f"{n:,}", money(c), money(c / n),
          "Single VPS" if c == 120 else ("2 vCPU VPS + managed DB" if c == 480 else "Load-balanced cluster")]
         for n, c in scale], [1.3, 1.5, 1.4, 2.0], center_cols=(0, 1, 2))

    H3("2.3.8 Comparison with Commercial Alternatives")
    TBL("Indicative Cost Comparison of Monitoring Options",
        ["Option", "Upfront (USD)", "Recurring", "Vendor Lock-in", "Plain-language Alerts"], [
            ["Smart Solar Alert (this project)", money(m["capex"]), f"{money(m['opex'])}/yr", "None (open stack)", "Yes"],
            ["Victron Cerbo GX + VRM portal", "\u2248 $300+", "Free portal", "Victron hardware", "Partial"],
            ["Inverter-vendor Wi-Fi dongle", "\u2248 $60\u2013$120", "Free app", "Single inverter brand", "Limited"],
            ["Monthly manual technician inspection", "$0", "\u2248 $180/yr", "None", "Only on visit"],
        ], [2.0, 1.0, 1.0, 1.3, 1.1])
    P("Figures for commercial products are indicative market prices and vary by supplier; they are "
      "included to position the project, not as quotations.", italic=True, size=9)


