def _boundary_cases():
    vn, vx, vl, vh = G.V_NORM_MIN, G.V_NORM_MAX, G.V_CRIT_LOW, G.V_CRIT_HIGH
    inn, il = G.I_NORM_MIN, G.I_CRIT_LOW
    mid_v = round((vn + vx) / 2, 2)
    return [
        ("Nominal operation", mid_v, inn + 1.0),
        ("Zero input (night)", 0.0, 0.0),
        ("Just below critical-low V", max(vl - 0.1, 0.0), inn + 0.5),
        ("At normal-max V", vx, inn + 0.5),
        ("Just above normal-max V", round(vx + 0.1, 2), inn + 0.5),
        ("Above critical-high V", round(vh + 0.5, 2), inn + 0.5),
        ("Low current (shading)", mid_v, round((inn + il) / 2, 2)),
        ("Critically low current", mid_v, max(il - 0.1, 0.0)),
    ]


def chapter5_extra():
    H2("5.7 Live Boundary-Value Test Results")
    P("**Innovation:** instead of typing expected outcomes by hand, the documentation generator "
      "*executes the real diagnostic engine* on each boundary case at build time. The table below is "
      "therefore an executable specification \u2014 if a threshold changes in code, this table changes "
      "with it.")
    TBL("Boundary-Value Analysis (Executed Against Live Engine)",
        ["Case", "Voltage (V)", "Current (A)", "Engine Conditions", "Severity"],
        [[n, f"{v:.2f}", f"{i:.2f}", G.run_engine(v, i), G.run_engine_severity(v, i)]
         for n, v, i in _boundary_cases()],
        [1.8, 0.8, 0.8, 2.0, 0.9], center_cols=(1, 2, 4))

